  function renderJourney(){const clients=customerUniverse(),group={};Object.keys(stages).forEach(k=>group[k]=[]);clients.forEach(c=>(group[boardBucket(c)]||group.inquiry).push(c));$("#journeyBoard").innerHTML=Object.entries(stages).map(([key,s])=>`<section class="journey-column" data-drop-stage="${key}"><div class="journey-column-head"><div class="label-wrap"><i class="stage-dot ${s.dot}"></i><h3>${s.title}</h3></div><span class="stage-count">${group[key].length}</span></div><div class="stage-copy">${s.copy}</div><div class="journey-cards">${group[key].map(clientCard).join("")}</div></section>`).join("");bindJourneyDnD();bindClientOpeners()}
  function clientCard(c){const n=nextBooking(c.email),pkg=activePackage(c.email),inv=clientData(c.email).invoices.find(x=>x.status==="overdue");return `<article class="client-card" draggable="true" data-client-email="${esc(c.email)}"><h4>${esc(c.name)}</h4><div class="card-email">${esc(visibleContactEmail(c.contactEmail||c.email))}${c.isSandboxProfile?` <span class="badge test">Sandbox/Testprofil</span>`:""}</div><div class="card-meta">${n?`<span>📅 ${esc(dt(n.start))}</span>`:""}${pkg?`<span>▣ ${esc(pkg.productName)} · ${pkg.remaining}/${pkg.total}</span>`:""}</div><div class="card-flags">${pkg&&Number(pkg.remaining)<=loadSettings().renewalRemaining?`<span class="flag warn">Fortsetzung</span>`:""}${inv?`<span class="flag alert">Rechnung überfällig</span>`:""}</div><button class="card-open" type="button" data-open-client="${esc(c.email)}">Akte öffnen →</button></article>`}
  function bindJourneyDnD(){let dragged="";$$('.client-card[draggable="true"]').forEach(card=>{card.addEventListener('dragstart',e=>{dragged=card.dataset.clientEmail;card.classList.add('dragging');e.dataTransfer.effectAllowed='move'});card.addEventListener('dragend',()=>{card.classList.remove('dragging');$$('.journey-column').forEach(c=>c.classList.remove('drag-over'))})});$$('[data-drop-stage]').forEach(col=>{col.addEventListener('dragover',e=>{e.preventDefault();col.classList.add('drag-over')});col.addEventListener('dragleave',()=>col.classList.remove('drag-over'));col.addEventListener('drop',e=>{e.preventDefault();col.classList.remove('drag-over');if(!dragged)return;moveClient(dragged,col.dataset.dropStage);dragged=""})})}
  function moveClient(email,stage){const c=customerUniverse().find(x=>x.email===normEmail(email));if(!c)return;const life=loadLifecycle();const prospect=life.prospects.find(p=>normEmail(p.email)===c.email);if(prospect&&!c.backend){prospect.stage=stage;prospect.updatedAt=new Date().toISOString();saveLifecycle(life);post('/admin/crm/inquiry/update',{id:prospect.id,email:prospect.email,journeyStage:stage,status:stage==='completed'?'closed':'open'}).catch(e=>alert('Journey konnte nicht gespeichert werden: '+e.message));logLocal(email,'journey',`Journey: ${stages[stage]?.title||stage}`);renderAll();return}const patch={journeyStage:stage};if(stage==='active')patch.clientStatus='active';else if(stage==='paused')patch.clientStatus='paused';else if(stage==='completed')patch.clientStatus='completed';else patch.clientStatus='prospect';setLifecycle(email,patch,'per Drag & Drop');renderAll()}

