  function renderClients(){const q=String($("#clientSearch").value||"").trim().toLowerCase(),filter=$("#clientStatusFilter").value;let cs=customerUniverse().filter(c=>!q||`${c.name} ${c.contactEmail||''} ${c.email}`.toLowerCase().includes(q));if(filter!=="all")cs=cs.filter(c=>lifecycleOf(c).clientStatus===filter);const rows=cs.map(c=>{const l=lifecycleOf(c),n=nextBooking(c.email),pkg=activePackage(c.email),open=clientData(c.email).invoices.filter(x=>x.status==="open"||x.status==="overdue").reduce((s,x)=>s+Number(x.totalCents||0),0);return `<tr><td><span class="name">${esc(c.name)}</span><div class="sub">${esc(visibleContactEmail(c.contactEmail||c.email))}${c.isSandboxProfile?' · 🧪 Sandbox/Test':''}</div></td><td>${clientStatusBadge(l.clientStatus)}</td><td>${esc(stages[boardBucket(c)]?.title||"—")}</td><td>${n?esc(dt(n.start)):"—"}</td><td>${pkg?`${esc(pkg.productName)}<div class="sub">${pkg.remaining}/${pkg.total} offen</div>`:"—"}</td><td>${open?money(open):"—"}</td><td><button class="mini" data-open-client="${esc(c.email)}">Akte öffnen</button></td></tr>`});$("#clientsTable").innerHTML=cs.length?table(["Klient:in","Status","Phase","Nächster Termin","Package","Offen",""],rows):`<div class="empty">Keine Klient:innen gefunden.</div>`;bindClientOpeners()}
