  function bindClientOpeners(){$$('[data-open-client]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',e=>{e.stopPropagation();openClient(b.dataset.openClient)})})}
  function openClient(email){const c=customerUniverse().find(x=>x.email===normEmail(email));if(!c)return;currentRecordEmail=c.email;currentRecordTab='overview';$("#recordName").textContent=c.name;$("#recordEmail").textContent=visibleContactEmail(c.contactEmail||c.email)+(c.isSandboxProfile?" · Sandbox/Testprofil":"");$("#recordStatus").value=lifecycleOf(c).clientStatus;if(!$("#recordRenameBtn")){const status=$("#recordStatus")?.closest('.record-status');status?.insertAdjacentHTML('beforebegin','<button class="mini edit" id="recordRenameBtn" type="button">Name korrigieren</button>');$("#recordRenameBtn")?.addEventListener('click',renameCurrentClient)}$$('[data-record-tab]').forEach(b=>b.classList.toggle('active',b.dataset.recordTab==='overview'));renderRecord();$("#clientDialog").showModal()}
  $("#clientDialogClose").setAttribute("title","Klientenakte schließen");$("#clientDialogClose").setAttribute("aria-label","Klientenakte schließen");$("#clientDialogClose").addEventListener('click',()=>$("#clientDialog").close());$$('[data-record-tab]').forEach(b=>b.addEventListener('click',()=>{currentRecordTab=b.dataset.recordTab;$$('[data-record-tab]').forEach(x=>x.classList.toggle('active',x===b));renderRecord()}));
