    if(currentRecordTab==='invoices'){$("#recordContent").innerHTML=cd.invoices.length?table(["Honorarnote","Betrag","Fällig","Status","Zahlung","Aktion"],cd.invoices.map(x=>`<tr><td>${esc(x.invoiceNumber)}</td><td>${money(x.totalCents,x.currency)}</td><td>${dateOnly(x.dueDate)}</td><td>${statusLabel(x.status)}${x.dbStatus==='test'?' · Sandbox/Test':''}</td><td>${x.status==='paid'?`${esc(paymentLabel(x.paymentMethod))}<div class="sub">${dt(x.paidAt)}</div>`:'—'}</td><td><div class="row-actions"><button class="mini" data-pdf="${x.id}">PDF</button>${invoicePayable(x)?`<button class="mini pay" data-paid="${x.id}">Zahlung erfassen</button>`:''}</div></td></tr>`)):`<div class="empty">Keine Honorarnoten.</div>`;bindInvoiceActions()}
    if(currentRecordTab==='documentation'){$("#recordContent").innerHTML=`<div id="vaultRecordMount" class="vault-doc"><div class="vault-empty">Secure Practice Vault wird geladen …</div></div>`;document.dispatchEvent(new CustomEvent('bd:vault-record',{detail:{email:c.email,name:c.name}}))}
    if(currentRecordTab==='activity')$("#recordContent").innerHTML=activityHtml(c.email,80);
