  function activitiesFor(email){const cd=clientData(email),items=[];loadLifecycle().activities.filter(x=>x.email===email).forEach(x=>items.push({at:x.at,title:x.summary,detail:x.detail||'CRM-Aktion'}));cd.bookings.forEach(x=>items.push({at:x.start,title:x.status==='cancelled'?'Termin abgesagt':'Termin',detail:`${x.typeLabel} · ${x.locationLabel}`}));cd.invoices.forEach(x=>items.push({at:x.invoiceDate||x.dueDate,title:`Honorarnote ${x.invoiceNumber}`,detail:`${money(x.totalCents,x.currency)} · ${statusLabel(x.status)}`}));cd.packages.forEach(x=>items.push({at:x.purchasedAt||x.createdAt||x.expiresAt,title:`Package ${x.productName}`,detail:`${x.remaining}/${x.total} Einheiten offen`}));const backend=(data.activities||data.auditLog||data.audit||[]).filter(x=>normEmail(x.email||x.customerEmail)===email);backend.forEach(x=>items.push({at:x.createdAt||x.at||x.timestamp,title:x.summary||x.action||x.type||'Aktivität',detail:x.detail||''}));return items.filter(x=>x.at).sort((a,b)=>new Date(b.at)-new Date(a.at))}
  function activityIcon(x){const t=`${x?.title||''} ${x?.detail||''}`.toLowerCase();if(/whatsapp/.test(t))return'💬';if(/e-mail|email|mail /.test(t))return'✉️';if(/telefon|anruf/.test(t))return'📞';if(/zahlung|betrag erhalten|bezahlt|stripe|barzahlung|überweisung/.test(t))return'🏦';if(/rechnung|honorar/.test(t))return'🧾';if(/termin|buchung|storn/.test(t))return'📅';if(/package|paket|einheit/.test(t))return'📦';if(/ziel/.test(t))return'🎯';if(/diktat|audio|sprach/.test(t))return'🎙️';if(/handnotiz|handschrift/.test(t))return'✍️';if(/datei|dokument|artefakt|foto|bild/.test(t))return'📎';if(/sitzung|session|erstgespräch/.test(t))return'📝';if(/anfrage|kontakt|website|nachricht/.test(t))return'👤';return'•'}
  function activityHtml(email,limit){const a=activitiesFor(email).slice(0,limit);return a.length?`<div class="timeline">${a.map(x=>`<div class="timeline-item"><div class="timeline-mark timeline-mark-icon" aria-hidden="true">${activityIcon(x)}</div><div class="timeline-copy"><strong>${esc(x.title)}</strong><span>${esc(dt(x.at))}${x.detail?' · '+esc(x.detail):''}</span></div></div>`).join('')}</div>`:`<div class="empty">Noch keine Aktivität.</div>`}

