    $$('[data-package-edit]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',()=>{const x=findPackage(b.dataset.packageEdit);if(!x)return;openEditor({eyebrow:'Package',title:'Package bearbeiten',subtitle:`${x.customerName} · ${x.productName}`,email:x.customerEmail,fields:[{key:'remaining',label:'Offene Einheiten',type:'number',value:String(x.remaining),min:0},{key:'total',label:'Gesamte Einheiten',type:'number',value:String(x.total),min:0},{key:'expiresAt',label:'Gültig bis',type:'date',value:x.expiresAt?String(x.expiresAt).slice(0,10):'',display:v=>v?dateOnly(v):'ohne Ablaufdatum'}],save:v=>{const remaining=Number(v.remaining),total=Number(v.total);if(!Number.isInteger(remaining)||!Number.isInteger(total)||remaining<0||total<0||remaining>total)throw new Error('Offene Einheiten müssen zwischen 0 und der Gesamtzahl liegen.');return post('/admin/package/update',{creditId:x.creditId,remaining,total,expiresAt:v.expiresAt||null})},notify:()=>post('/admin/package/notify',{creditId:Number(x.creditId)})})})});
    $$('[data-due-edit]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',()=>{const x=findInvoice(b.dataset.dueEdit);if(!x)return;openEditor({eyebrow:'Rechnung',title:'Zahlungsziel ändern',subtitle:`${x.invoiceNumber} · ${x.customerName}`,email:x.customerEmail,fields:[{key:'dueDate',label:'Neues Zahlungsziel',type:'date',value:x.dueDate||'',display:dateOnly}],save:v=>post('/admin/invoice/update-due',{invoiceId:x.id,dueDate:v.dueDate}),notify:()=>post('/admin/invoice/notify',{invoiceId:Number(x.id)})})})})
