  function openSalesOrder(productId){const c=customerByEmail(currentRecordEmail),p=catalogProduct(productId);if(!c||!p)return;salesCtx={client:c,product:p};const bill=(b9().billing||[]).find(x=>Number(x.customer_id)===Number(c.id)||normEmail(x.email)===c.email)||{};$('#salesOrderTitle').textContent=p.name_de;$('#salesOrderClient').textContent=`${c.name} · ${visibleContactEmail(c.contactEmail||c.email)}`;const saving=Number(p.savingCents||0);$('#salesOrderSummary').innerHTML=`<strong>${esc(p.name_de)} · ${money(Number(p.priceCents||0))}</strong><span>${p.sessions_total?`${p.sessions_total} × ${p.session_minutes} Min. · `:''}${saving?`${money(saving)} Paketvorteil · `:''}Package wird erst nach Zahlung aktiviert.</span>`;$('#salesStreet').value=bill.billing_street||'';$('#salesPostal').value=bill.billing_postal_code||'';$('#salesCity').value=bill.billing_city||'';$('#salesCountry').value=bill.billing_country||'Österreich';$('#salesIncludeStripe').checked=true;$('#salesEarlyService').checked=false;$('#salesImmediateDigital').checked=false;$('#salesOrderMsg').textContent='';$('#salesOrderDialog').showModal()}
  $('#salesOrderClose').onclick=$('#salesOrderCancel').onclick=()=>$('#salesOrderDialog').close();
  $('#salesOrderForm').addEventListener('submit',async e=>{e.preventDefault();if(!salesCtx)return;const b={customerId:salesCtx.client.id,email:salesCtx.client.email,productId:salesCtx.product.id,includeStripe:$('#salesIncludeStripe').checked,locale:'de',billing:{street:$('#salesStreet').value.trim(),postal:$('#salesPostal').value.trim(),city:$('#salesCity').value.trim(),country:$('#salesCountry').value.trim()},consents:{earlyService:$('#salesEarlyService').checked,immediateDigital:$('#salesImmediateDigital').checked}};const submit=e.submitter;submit.disabled=true;try{const x=await post('/admin/sales/order',b);message($('#salesOrderMsg'),`Bestellung ${x.invoiceNumber||''} wurde angelegt${x.emailSent?' und per E-Mail versendet.':'.'}`);setTimeout(async()=>{$('#salesOrderDialog').close();await load();currentRecordTab='sales';renderRecord()},900)}catch(err){message($('#salesOrderMsg'),err.message,'err')}finally{submit.disabled=false}});

  async function openCancellation(eventId){const x=findBooking(eventId);if(!x)return;try{const o=await api('/admin/booking/cancel-options?eventId='+encodeURIComponent(eventId)),f=o.finance||{};cancelCtx={booking:x,finance:f};$('#cancelClient').textContent=`${x.name} · ${dt(x.start)} · ${x.typeLabel}`;const charge=Number(f.chargePercent??0),ref=Number(f.refundableCents||0),total=Number(f.totalCents||0),fee=Number(f.cancellationFeeCents||0);let summary='';if(f.packageCredit)summary='Package-Termin · Einheit wird zurückgebucht.';else if(f.isPaid)summary=total?`Bezahlter Betrag ${money(total)} · erstattungsfähig ${money(ref)}`:'Bezahlte Einzelrechnung nicht gefunden.';else if(f.invoiceId)summary=charge===0?`Offene Rechnung ${esc(f.invoiceNumber||'')} wird storniert · keine Gebühr.`:`Offene Rechnung ${esc(f.invoiceNumber||'')} · Stornogebühr ${money(fee)} (${charge}%).`;else summary='Keine zugeordnete Einzelrechnung gefunden.';$('#cancelSummary').innerHTML=`<strong>Stornoregel: ${charge}% Gebühr</strong><span>${summary}</span>`;let html='';if(f.packageCredit){html='<div class="policy-result">Dieser Termin wurde aus einem Package gebucht. Die verwendete Einheit wird dem Package wieder gutgeschrieben.</div>'}else if(f.isPaid&&ref>0){html=`<label class="settlement-option"><input type="radio" name="cancelSettlement" value="wallet" checked><span><strong>Als Guthaben in der Member Area</strong><span>${money(ref)} werden als Praxisguthaben hinterlegt.</span></span></label>${f.paymentMethod==='stripe'?`<label class="settlement-option"><input type="radio" name="cancelSettlement" value="refund"><span><strong>Auf ursprüngliches Zahlungsmittel zurückerstatten</strong><span>${money(ref)} werden über Stripe zurückerstattet.</span></span></label>`:''}`}else if(!f.isPaid&&f.invoiceId){html=`<div class="policy-result"><strong>${charge===0?'Offene Rechnung wird storniert':'Stornorechnung wird erstellt'}</strong><br>${charge===0?'Es bleibt kein Betrag offen.':`Die ursprüngliche Rechnung wird storniert; neu verrechnet werden ${money(fee)}.`}</div>`}else{html=`<div class="policy-result"><strong>Stornogebühr gemäß Bedingungen</strong><br>Aufgrund der Stornofrist besteht kein erstattungsfähiger Betrag. Die Stornierung kann trotzdem durchgeführt werden.</div>`}$('#cancelChoices').innerHTML=html;$('#cancelNotify').checked=true;$('#cancelDialog').showModal()}catch(e){alert(e.message)}}
  $('#cancelClose').onclick=$('#cancelAbort').onclick=()=>$('#cancelDialog').close();
  $('#cancelConfirm').addEventListener('click',async()=>{if(!cancelCtx)return;const f=cancelCtx.finance||{},settlement=f.packageCredit?'package_credit':Number(f.refundableCents||0)>0?(document.querySelector('input[name="cancelSettlement"]:checked')?.value||'wallet'):'policy';if(!confirm('Termin jetzt verbindlich stornieren? Diese Aktion entfernt ihn aus dem Google Kalender.'))return;const b=$('#cancelConfirm');b.disabled=true;b.textContent='Storniere …';try{await post('/admin/booking/cancel-settlement',{eventId:cancelCtx.booking.eventId,settlement,notifyCustomer:$('#cancelNotify').checked});$('#cancelDialog').close();await load()}catch(e){alert(e.message)}finally{b.disabled=false;b.textContent='Termin verbindlich stornieren'}});

  let pendingBankMatches=[];
  function parseCsvLine(line,sep){const out=[];let cur='',quote=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'){if(quote&&line[i+1]==='"'){cur+='"';i++}else quote=!quote}else if(ch===sep&&!quote){out.push(cur);cur=''}else cur+=ch}out.push(cur);return out.map(x=>x.trim())}
  function normalizeHeader(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim()}
  function parseEuroAmount(s){let v=String(s||'').trim().replace(/\s|€/g,'');if(!v)return NaN;if(v.includes(',')&&v.includes('.'))v=v.lastIndexOf(',')>v.lastIndexOf('.')?v.replace(/\./g,'').replace(',','.'):v.replace(/,/g,'');else if(v.includes(','))v=v.replace(/\./g,'').replace(',','.');return Number(v)}
  function parseBankDate(s){s=String(s||'').trim();let m;if(/^\d{4}-\d{2}-\d{2}/.test(s))return s.slice(0,10);if((m=s.match(/^(\d{1,2})[.\/]\s*(\d{1,2})[.\/]\s*(\d{4})/)))return `${m[3]}-${String(m[2]).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`;return null}
  function pickHeader(headers,names){for(const name of names){const i=headers.findIndex(h=>h===name||h.includes(name));if(i>=0)return i}return -1}
  function csvTransactions(text){const lines=String(text||'').replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());if(lines.length<2)throw new Error('CSV enthält keine Daten.');const sample=lines.slice(0,5).join('\n'),sep=(sample.match(/;/g)||[]).length>=(sample.match(/,/g)||[]).length?';':',';const headers=parseCsvLine(lines[0],sep).map(normalizeHeader);const dateI=pickHeader(headers,['buchungsdatum','valutadatum','datum','booking date','date']);const amountI=pickHeader(headers,['betrag eur','betrag','umsatz','amount']);const refIs=['verwendungszweck','buchungstext','zahlungsreferenz','referenz','reference','memo','purpose','text'].map(n=>pickHeader(headers,[n])).filter((v,i,a)=>v>=0&&a.indexOf(v)===i);const cpI=pickHeader(headers,['zahlungsbeteiligter','auftraggeber','gegenkonto name','empfanger auftraggeber','counterparty','payer','name']);if(dateI<0||amountI<0)throw new Error('Datum- oder Betragsspalte konnte nicht erkannt werden. Exportiere bitte ein CSV mit Buchungsdatum/Valutadatum und Betrag.');const tx=[];for(let i=1;i<lines.length;i++){const row=parseCsvLine(lines[i],sep),amount=parseEuroAmount(row[amountI]);if(!Number.isFinite(amount)||amount<=0)continue;const date=parseBankDate(row[dateI]);if(!date)continue;const reference=refIs.map(j=>row[j]||'').filter(Boolean).join(' · ');tx.push({row:i+1,paymentDate:date,amountCents:Math.round(amount*100),reference,counterparty:cpI>=0?(row[cpI]||''):''})}return tx}
  function confidenceBadge(c){return c==='exact'?'<span class="badge paid">Sicher erkannt</span>':c==='probable'?'<span class="badge open">Wahrscheinlich</span>':c==='amount_only'?'<span class="badge neutral">Nur Betrag</span>':'<span class="badge neutral">Offen</span>'}
  async function handleBankCsv(file){pendingBankSource=file.name||'Bank-CSV';const transactions=csvTransactions(await file.text());pendingBankRowCount=transactions.length;if(!transactions.length)throw new Error('Keine eingehenden Zahlungen erkannt.');const x=await post('/admin/payments/match',{transactions});pendingBankMatches=(x.matches||[]).map(m=>({...transactions[m.index],...m}));const exact=pendingBankMatches.filter(x=>x.confidence==='exact').length,probable=pendingBankMatches.filter(x=>x.confidence==='probable').length;$("#bankImportSummary").textContent=`${transactions.length} eingehende Buchungen · ${exact} sicher zugeordnet · ${probable} wahrscheinlich. Sichere Treffer sind vorausgewählt.`;$("#bankImportTable").innerHTML=table(['Übernehmen','Datum','Betrag','Absender / Referenz','Zuordnung','Sicherheit'],pendingBankMatches.map((m,i)=>`<tr><td>${m.invoiceId?`<input type="checkbox" data-bank-match="${i}" ${m.confidence==='exact'?'checked':''}>`:'—'}</td><td>${dateOnly(m.paymentDate)}</td><td>${money(m.amountCents)}</td><td>${esc(m.counterparty||'—')}<div class="sub">${esc(m.reference||'')}</div></td><td>${m.invoiceId?`${esc(m.invoiceNumber)}<div class="sub">${esc(m.customerName||'')}</div>`:'Keine eindeutige Rechnung'}</td><td>${confidenceBadge(m.confidence)}<div class="sub">${esc(m.reason||'')}</div></td></tr>`));$("#bankImportDialog").showModal()}
  $("#bankCsvInput").addEventListener('change',async e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;try{await handleBankCsv(f)}catch(err){alert('CSV-Import: '+err.message)}});$("#bankImportClose").onclick=$("#bankImportCancel").onclick=()=>$("#bankImportDialog").close();$("#bankImportApply").addEventListener('click',async()=>{const selected=$$('[data-bank-match]:checked').map(el=>pendingBankMatches[Number(el.dataset.bankMatch)]).filter(Boolean).map(x=>({invoiceId:x.invoiceId,paymentDate:x.paymentDate,amountCents:x.amountCents,reference:x.reference,counterparty:x.counterparty}));if(!selected.length){alert('Bitte mindestens eine erkannte Zahlung auswählen.');return}if(!confirm(`${selected.length} Zahlung${selected.length===1?'':'en'} jetzt als Banküberweisung verbuchen?`))return;const b=$("#bankImportApply");b.disabled=true;b.textContent='Übernehme …';try{const x=await post('/admin/payments/import',{matches:selected,sourceName:pendingBankSource,rowCount:pendingBankRowCount});alert(`${x.imported||0} Zahlung${Number(x.imported)===1?'':'en'} übernommen.`);$("#bankImportDialog").close();await load()}catch(e){alert(e.message)}finally{b.disabled=false;b.textContent='Ausgewählte Zahlungen übernehmen'}});

  function renderSettings(){const s=loadSettings();$("#settingDormantDays").value=s.dormantDays;$("#settingRenewalRemaining").value=s.renewalRemaining;$("#settingDiscount").value=s.discount}
  $("#saveSettingsBtn").addEventListener('click',async()=>{const cfg={dormantDays:Number($("#settingDormantDays").value||60),renewalRemaining:Number($("#settingRenewalRemaining").value||1),discount:Number($("#settingDiscount").value||0)};try{crmState.settings=cfg;await post('/admin/crm/settings',cfg);message($("#settingsMsg"),'Einstellungen im Worker gespeichert.');renderAll()}catch(e){message($("#settingsMsg"),'Speichern fehlgeschlagen: '+e.message,'err')}});
  $("#exportLifecycleBtn").addEventListener('click',()=>{const payload={version:1,exportedAt:new Date().toISOString(),lifecycle:loadLifecycle(),settings:loadSettings()};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='beziehungsdynamiken-crm-status-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1200)});
  if($("#importLifecycleInput")) $("#importLifecycleInput").addEventListener('change',async e=>{e.target.value='';message($("#settingsMsg"),'Import ist in BUILD 9 bewusst deaktiviert, weil CRM-Status jetzt serverseitig in D1 gespeichert wird. Nutze für Migrationen die D1-Sicherung.','err')});

  (async()=>{if(!API){showLogin();message($("#loginMsg"),'Die API-Adresse ist noch nicht konfiguriert.','err');return}const magic=await consumeMagicLink();if(session||magic)await load();else showLogin()})();
